let state,role="barber",view="dashboard",selectedIncident="Atraso",selectedBarber=0,selectedDayKey="",pendingActions=[],recentApprovedActions=[],coachApprovedActions=[],teamMembers=[],teamIncidents=[],stateLoaded=false,progressPoll,operationPoll,lastRank=null,accessFormDraft={};
state=JSON.parse(JSON.stringify(initial));
