const actionIcons={cortes:"✂",barbas:"≋",extras:"✦",produtos:"▣",assinaturas:"★"};actions.forEach(action=>{if(actionIcons[action.key])action.icon=actionIcons[action.key]});
function dateKeySP(input=new Date()){const parts=new Intl.DateTimeFormat("en-CA",{timeZone:"America/Sao_Paulo",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date(input)),get=type=>parts.find(part=>part.type===type)?.value;return get("year")+"-"+get("month")+"-"+get("day")}
function formatDateTimeSP(input){return new Intl.DateTimeFormat("pt-BR",{timeZone:"America/Sao_Paulo",day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(new Date(input))}
function parseBrazilDate(value){const parts=String(value||"").split("/").map(Number);return parts.length===3&&parts.every(Number.isFinite)?new Date(parts[2],parts[1]-1,parts[0],12):null}
function formatBrazilDate(date){return new Intl.DateTimeFormat("pt-BR",{timeZone:"America/Sao_Paulo",day:"2-digit",month:"2-digit",year:"numeric"}).format(date)}
function currentMonthSeason(){const now=new Date(),sp=new Date(now.toLocaleString("en-US",{timeZone:"America/Sao_Paulo"})),first=new Date(sp.getFullYear(),sp.getMonth(),1,12),last=new Date(sp.getFullYear(),sp.getMonth()+1,0,12),month=new Intl.DateTimeFormat("pt-BR",{month:"long"}).format(first);return{name:"Temporada "+month.charAt(0).toUpperCase()+month.slice(1)+" "+sp.getFullYear(),start:formatBrazilDate(first),end:formatBrazilDate(last),prize:state?.season?.prize||initial.season.prize,active:true}}
function defaultCampaignDraft(){const now=new Date(),sp=new Date(now.toLocaleString("en-US",{timeZone:"America/Sao_Paulo"})),first=new Date(sp.getFullYear(),sp.getMonth()+1,1,12),last=new Date(sp.getFullYear(),sp.getMonth()+2,0,12),month=new Intl.DateTimeFormat("pt-BR",{month:"long"}).format(first),campaignPoints={cortes:5,barbas:5,extras:20,produtos:30,assinaturas:60};return{name:"Gincana de "+month.charAt(0).toUpperCase()+month.slice(1),start:formatBrazilDate(first),end:formatBrazilDate(last),prize:"Prêmio especial + destaque da campanha",minimumPoints:300,bonusGoal:10,bonusValue:150,status:"draft",rules:actions.map(action=>({key:action.key,label:action.label,icon:action.icon,points:campaignPoints[action.key]??10}))}}
function campaignDraft(){if(!state.nextCampaign)state.nextCampaign=defaultCampaignDraft();state.nextCampaign.rules=Array.isArray(state.nextCampaign.rules)&&state.nextCampaign.rules.length?state.nextCampaign.rules:defaultCampaignDraft().rules;return state.nextCampaign}
function seasonInfo(){let season=state.season||currentMonthSeason(),start=parseBrazilDate(season.start),end=parseBrazilDate(season.end),today=parseBrazilDate(formatBrazilDate(new Date()));if(!start||!end||end<today){state.season=currentMonthSeason();season=state.season;start=parseBrazilDate(season.start);end=parseBrazilDate(season.end)}const total=Math.max(1,Math.round((end-start)/86400000)+1),elapsed=Math.max(0,Math.min(total,Math.round((today-start)/86400000)+1)),remaining=Math.max(0,Math.ceil((end-today)/86400000)),active=today>=start&&today<=end;season.active=active;return{season,start,end,active,remaining,progress:Math.round(elapsed/total*100)}}
const todayKey=dateKeySP();selectedDayKey=todayKey;if(state.dayKey!==todayKey){state.dayKey=todayKey;state.dailyCounts={cortes:0,barbas:0,extras:0,produtos:0,assinaturas:0}}else if(!state.dailyCounts){state.dailyCounts={cortes:0,barbas:0,extras:0,produtos:0,assinaturas:0}}
if(!state.dailyStats)state.dailyStats={};
const emptyDaily=()=>({cortes:0,barbas:0,extras:0,produtos:0,assinaturas:0}),monthKey=todayKey.slice(0,7);
function calculateStreak(){const active=new Set(Object.entries(state.dailyStats||{}).filter(([,value])=>Number(value)>0).map(([key])=>key));let cursor=new Date(todayKey+"T12:00:00-03:00");if(!active.has(todayKey))cursor.setDate(cursor.getDate()-1);let streak=0;for(let guard=0;guard<370;guard++){if(cursor.getDay()===0){cursor.setDate(cursor.getDate()-1);continue}const key=dateKeySP(cursor);if(!active.has(key))break;streak++;cursor.setDate(cursor.getDate()-1)}return streak}
function normalizeDailyState(){state.dailyBreakdown=state.dailyBreakdown||{};state.dailyStats=state.dailyStats||{};if(state.dayKey!==todayKey){state.dayKey=todayKey;state.dailyCounts=emptyDaily()}state.dailyCounts={...emptyDaily(),...(state.dailyBreakdown[todayKey]||state.dailyCounts||{})};state.dailyBreakdown[todayKey]={...state.dailyCounts};state.dailyStats[todayKey]=Object.values(state.dailyCounts).reduce((sum,value)=>sum+(Number(value)||0),0);state.streak=calculateStreak()}
function normalizeMonthlyPoints(){normalizeDailyState();if(!state.pointsMonth)state.pointsMonth=monthKey;else if(state.pointsMonth!==monthKey){state.points=0;state.pointsMonth=monthKey;state.rewards=[]}}
function rebuildDailyActivity(rows=[]){const breakdown={};for(const row of rows){const key=dateKeySP(row.created_at),actionKey=row.action_key;if(!breakdown[key])breakdown[key]=emptyDaily();breakdown[key][actionKey]=(Number(breakdown[key][actionKey])||0)+1}state.dailyBreakdown=breakdown;state.dailyStats=Object.fromEntries(Object.entries(breakdown).map(([key,counts])=>[key,Object.values(counts).reduce((sum,value)=>sum+(Number(value)||0),0)]));state.dayKey=todayKey;state.dailyCounts={...emptyDaily(),...(breakdown[todayKey]||{})};state.streak=calculateStreak()}
function esc(s){return String(s).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}
function isOwner(){return currentProfile?.role==="leader"}
function isManager(){return currentProfile?.role==="manager"}
