function applyRemoteState(next){if(!next)return;if(stateLoaded){const oldXp=Number(state.xp)||0,newXp=Number(next.xp)||0,oldLevel=Math.floor(oldXp/500)+1,newLevel=Math.floor(newXp/500)+1,oldMissions=completedMissions(state);state=next;normalizeDailyState();const newMissions=completedMissions(state);if(newLevel>oldLevel)celebrate("Novo nível!","Você chegou ao nível "+newLevel+". Continue assim!","🏆");else if(newMissions>oldMissions)celebrate("Missão concluída!","Bônus de missão liberado. Excelente trabalho!","🎯");else if(newXp>oldXp)celebrate("Serviço aprovado!","Você ganhou "+(newXp-oldXp)+" XP.","✨")}else{state=next;normalizeDailyState();stateLoaded=true}}
async function refreshMyProgress(){if(!currentUser||!remoteReady||document.hidden)return;const requests=[supabaseClient.from("barber_states").select("state").eq("user_id",currentUser.id).single(),supabaseClient.from("barber_states").select("user_id,state")];if(currentProfile?.role==="leader")requests.push(supabaseClient.from("barber_actions").select("*,profiles!barber_actions_user_id_fkey(full_name,email)").eq("status","pending").order("created_at"));const [{data,error},rankingResult,actionsResult]=await Promise.all(requests);if(error||!data?.state)return;const before=JSON.stringify(state),beforePending=pendingActions.length;applyRemoteState(data.state);if(actionsResult){pendingActions=(actionsResult.data||[]).map(row=>{const p=Array.isArray(row.profiles)?row.profiles[0]:row.profiles||{};return{...row,full_name:p.full_name||"Barbeiro",email:p.email||""}});if(pendingActions.length>beforePending){toast("🔔 Novo serviço aguardando sua aprovação");if(navigator.vibrate)navigator.vibrate([90,60,90])}}const ranking=(rankingResult.data||[]).slice().sort((a,b)=>(Number(b.state?.points)||0)-(Number(a.state?.points)||0)),rank=ranking.findIndex(item=>item.user_id===currentUser.id)+1;if(rank>0){if(lastRank!==null&&rank<lastRank)celebrate("Subiu no ranking!","Agora você está na posição "+rank+".","👑");lastRank=rank}if(view!=="settings"&&(JSON.stringify(state)!==before||pendingActions.length!==beforePending))render()}
async function loadApprovedActions(){if(currentProfile?.role!=="leader")return;const since=new Date(Date.now()-35*86400000).toISOString(),{data,error}=await supabaseClient.from("barber_actions").select("*,profiles!barber_actions_user_id_fkey(full_name,email)").eq("status","approved").gte("created_at",since).order("reviewed_at",{ascending:false}).limit(1000);if(error)return;coachApprovedActions=(data||[]).map(row=>{const p=Array.isArray(row.profiles)?row.profiles[0]:row.profiles||{};return{...row,full_name:p.full_name||"Barbeiro",email:p.email||""}});recentApprovedActions=coachApprovedActions.slice(0,20);if(view==="approvals"||view==="leader"||view==="ai"||view==="ranking")render()}
async function loadSeasonLeaderboard(){const {data,error}=await supabaseClient.from("barber_states").select("user_id,state,profiles!barber_states_user_id_fkey(full_name,email)");if(error)return;for(const row of data||[]){const profile=Array.isArray(row.profiles)?row.profiles[0]:row.profiles||{},name=profile.full_name||profile.email||"Barbeiro",person=people.find(item=>item.name===name),saved=row.state||{};if(person){person.dailyCounts=saved.dailyCounts||{};person.dailyStats=saved.dailyStats||{};person.dailyBreakdown=saved.dailyBreakdown||{};person.incidents=saved.incidents||[];person.streak=Number(saved.streak)||0}}if(view==="ranking"||view==="ai")render()}
async function loadRemote(){try{const [stateResult,configResult,rankingResult,activityResult]=await Promise.all([supabaseClient.from("barber_states").select("state").eq("user_id",currentUser.id).single(),supabaseClient.from("app_configs").select("config_key,config_value"),supabaseClient.from("barber_states").select("user_id,state,profiles!barber_states_user_id_fkey(full_name,email)"),supabaseClient.from("barber_actions").select("action_key,created_at").eq("user_id",currentUser.id).eq("status","approved").order("created_at")]);if(stateResult.error)throw stateResult.error;applyRemoteState(stateResult.data?.state);if(!activityResult.error)rebuildDailyActivity(activityResult.data||[]);for(const item of configResult.data||[]){if(item.config_key==="rewards"&&Array.isArray(item.config_value))rewards=item.config_value;if(item.config_key==="missions"&&Array.isArray(item.config_value))missionRules=item.config_value}if(Array.isArray(rankingResult.data)&&rankingResult.data.length){const mapped=rankingResult.data.map(row=>{const s=row.state||{},profile=Array.isArray(row.profiles)?row.profiles[0]:row.profiles||{};return{name:profile.full_name||profile.email||"Barbeiro",initials:(profile.full_name||"BX").split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase(),me:row.user_id===currentUser.id,xp:Number(s.xp)||0,points:Number(s.points)||0,stats:s.counts||{}}});people.splice(0,people.length,...mapped);teamIncidents=rankingResult.data.flatMap(row=>{const profile=Array.isArray(row.profiles)?row.profiles[0]:row.profiles||{};return(row.state?.incidents||[]).map(item=>({...item,userId:row.user_id,person:item.person||profile.full_name||"Barbeiro"}))}).sort((a,b)=>String(b.createdAt||"").localeCompare(String(a.createdAt||"")));const rank=mapped.slice().sort((a,b)=>b.points-a.points).findIndex(item=>item.me)+1;if(rank>0)lastRank=rank}if(currentProfile.role==="leader"){const [actionsResult,membersResult]=await Promise.all([supabaseClient.from("barber_actions").select("*,profiles!barber_actions_user_id_fkey(full_name,email)").eq("status","pending").order("created_at"),supabaseClient.from("profiles").select("id,email,full_name,role,active,created_at").order("full_name")]);pendingActions=(actionsResult.data||[]).map(row=>{const p=Array.isArray(row.profiles)?row.profiles[0]:row.profiles||{};return{...row,full_name:p.full_name||"Barbeiro",email:p.email||""}});teamMembers=membersResult.data||[]}normalizeMonthlyPoints();remoteReady=true;scheduleSave();clearInterval(progressPoll);progressPoll=setInterval(refreshMyProgress,15000);render()}catch(e){remoteReady=false;try{const local=JSON.parse(localStorage.getItem("barberxp-cache-"+currentUser.id)||"null");if(local){if(local.state)state=local.state;if(Array.isArray(local.rewards))rewards=local.rewards;if(Array.isArray(local.missionRules))missionRules=local.missionRules;if(Array.isArray(local.actions))actions=local.actions}}catch(_){}normalizeMonthlyPoints();render();toast("Sem sincronização no momento",true)}}
function bind(){document.querySelectorAll("[data-view],[data-go]").forEach(b=>b.onclick=()=>{view=b.dataset.view||b.dataset.go;render();window.scrollTo(0,0)});document.querySelectorAll("[data-day-key]").forEach(b=>b.onclick=()=>{selectedDayKey=b.dataset.dayKey;render()});document.querySelectorAll(".register").forEach(b=>b.onclick=()=>register(b.dataset.key));document.querySelectorAll(".redeem").forEach(b=>b.onclick=()=>redeem(Number(b.dataset.index)));document.querySelectorAll(".barber-select").forEach(b=>b.onclick=()=>{selectedBarber=Number(b.dataset.barber);render()});document.querySelectorAll("[data-review]").forEach(b=>b.onclick=()=>reviewAction(Number(b.dataset.review),b.dataset.status));document.querySelectorAll(".ai-prompt").forEach(b=>b.onclick=()=>{const box=document.querySelector("#aiAnswer");box.innerHTML="<b>RECOMENDAÇÃO DO COACH</b><p>"+aiAdvice(b.dataset.ai)+"</p>"});document.querySelectorAll(".incident").forEach(b=>b.onclick=()=>{selectedIncident=b.dataset.incident;document.querySelectorAll(".incident").forEach(x=>x.classList.remove("active"));b.classList.add("active")});document.querySelectorAll("[data-remove]").forEach(b=>b.onclick=()=>{if(actions.length<=1)return;actions.splice(Number(b.dataset.remove),1);state.actionRules=actions;render()});document.querySelectorAll("[data-remove-reward]").forEach(b=>b.onclick=()=>{if(rewards.length<=1)return;rewards.splice(Number(b.dataset.removeReward),1);render()});document.querySelectorAll("[data-member-save]").forEach(b=>b.onclick=()=>saveMember(b.dataset.memberSave));document.querySelectorAll("[data-member-toggle]").forEach(b=>b.onclick=()=>toggleMember(b.dataset.memberToggle,b.dataset.active==="true"));document.querySelectorAll("[data-member-reset]").forEach(b=>b.onclick=()=>resetMemberPassword(b.dataset.email));const apply=document.querySelector("#applyIncident");if(apply)apply.onclick=applyIncident;const passwordButton=document.querySelector("#changeOwnPassword");if(passwordButton)passwordButton.onclick=changeOwnPassword;const profileLogout=document.querySelector("#profileLogout");if(profileLogout)profileLogout.onclick=logout;const add=document.querySelector("#addRule");if(add)add.onclick=()=>{const key="extra_"+Date.now();actions.push({key,label:"Novo serviço extra",desc:"Serviço personalizado",xp:10,points:1,icon:"✦"});state.counts[key]=0;state.dailyCounts[key]=0;state.actionRules=actions;render()};const save=document.querySelector("#saveRules");if(save)save.onclick=saveRules;const saveMissions=document.querySelector("#saveMissions");if(saveMissions)saveMissions.onclick=saveMissionSettings;const addReward=document.querySelector("#addReward");if(addReward)addReward.onclick=()=>{rewards.push({icon:"🎁",name:"Novo prêmio",desc:"Descreva a recompensa",price:100});render()};const saveRewards=document.querySelector("#saveRewards");if(saveRewards)saveRewards.onclick=saveRewardSettings;const season=document.querySelector("#saveSeason");if(season)season.onclick=saveSeasonSettings;const campaign=document.querySelector("#saveCampaignDraft");if(campaign)campaign.onclick=saveCampaignDraft;const member=document.querySelector("#prepareMember");if(member)member.onclick=createMember}
async function loadManagerData(){if(!canManageOperation())return;const since=new Date(Date.now()-35*86400000).toISOString(),[pendingResult,membersResult,approvedResult]=await Promise.all([supabaseClient.from("barber_actions").select("*,profiles!barber_actions_user_id_fkey(full_name,email)").eq("status","pending").order("created_at"),supabaseClient.from("profiles").select("id,email,full_name,role,active,created_at").order("full_name"),supabaseClient.from("barber_actions").select("*,profiles!barber_actions_user_id_fkey(full_name,email)").eq("status","approved").gte("created_at",since).order("reviewed_at",{ascending:false}).limit(1000)]);if(!pendingResult.error)pendingActions=(pendingResult.data||[]).map(row=>{const p=Array.isArray(row.profiles)?row.profiles[0]:row.profiles||{};return{...row,full_name:p.full_name||"Barbeiro",email:p.email||""}});if(!membersResult.error)teamMembers=membersResult.data||[];if(!approvedResult.error){coachApprovedActions=(approvedResult.data||[]).map(row=>{const p=Array.isArray(row.profiles)?row.profiles[0]:row.profiles||{};return{...row,full_name:p.full_name||"Barbeiro",email:p.email||""}});recentApprovedActions=coachApprovedActions.slice(0,20)}if(["manager","approvals","ai","ranking","leader"].includes(view))render()}
async function createManager(){if(!isOwner())return;const name=document.querySelector("#newManagerName")?.value.trim(),email=document.querySelector("#newManagerEmail")?.value.trim().toLowerCase(),password=document.querySelector("#newManagerPassword")?.value,status=document.querySelector("#managerStatus"),button=document.querySelector("#prepareManager");if(!name)return toast("Informe o nome do Gestor",true);if(!email||!email.includes("@"))return toast("Informe um e-mail válido",true);if(!password||password.length<6)return toast("A senha precisa ter pelo menos 6 caracteres",true);button.disabled=true;button.textContent="Criando acesso...";status.textContent="";const secondary=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false}}),{data,error}=await secondary.auth.signUp({email,password,options:{data:{full_name:name,role:"manager"}}});if(error){button.disabled=false;button.textContent="＋ Criar acesso de Gestor";status.style.color="#fca5a5";status.textContent=error.message.includes("already")?"Este e-mail já está cadastrado.":"Não foi possível criar o acesso agora.";return}await new Promise(resolve=>setTimeout(resolve,600));const roleUpdate=await supabaseClient.from("profiles").update({role:"manager",full_name:name,updated_at:new Date().toISOString()}).eq("id",data.user.id);button.disabled=false;button.textContent="＋ Criar acesso de Gestor";if(roleUpdate.error){status.style.color="#fca5a5";status.textContent="A conta foi criada, mas o perfil de Gestor não foi aplicado. Execute a atualização do banco e tente novamente.";return}status.style.color="#4ade80";status.textContent="Gestor criado. Ele poderá acompanhar, aprovar e enviar feedbacks.";accessFormDraft.newManagerName="";accessFormDraft.newManagerEmail="";accessFormDraft.newManagerPassword="";document.querySelector("#newManagerName").value="";document.querySelector("#newManagerEmail").value="";document.querySelector("#newManagerPassword").value="";loadManagerData();toast("Acesso de Gestor criado com sucesso")}
async function updateMemberRole(id,nextRole){if(!isOwner()||!["barber","manager"].includes(nextRole))return;const member=teamMembers.find(item=>item.id===id);if(!member)return;if(!confirm("Alterar "+member.full_name+" para "+roleName(nextRole)+"?")){render();return}const {error}=await supabaseClient.from("profiles").update({role:nextRole,updated_at:new Date().toISOString()}).eq("id",id);if(error)return toast("Não foi possível alterar a função",true);member.role=nextRole;pruneManagerPeople();toast(member.full_name+" agora é "+roleName(nextRole))}
async function reviewWithIdentity(id,status){const pending=pendingActions.find(action=>String(action.id)===String(id)),reviewer=currentProfile?.full_name||roleName();await reviewAction(id,status);await supabaseClient.from("barber_actions").update({reviewed_by_name:reviewer}).eq("id",id);const item=recentApprovedActions.find(action=>String(action.id)===String(id));if(item)item.reviewed_by_name=reviewer;if(status==="approved"&&pending){const result=await supabaseClient.from("barber_states").select("state").eq("user_id",pending.user_id).single();if(!result.error&&result.data?.state){const target=result.data.state;target.history=(target.history||[]).map(entry=>entry[6]==="action:"+id?[...entry.slice(0,3),String(entry[3]||"").replace("Aprovado pelo líder","Aprovado por "+reviewer),...entry.slice(4)]:entry);await supabaseClient.from("barber_states").update({state:target,updated_at:new Date().toISOString()}).eq("user_id",pending.user_id)}}if(view==="approvals")render()}
async function logout(){await supabaseClient.auth.signOut();location.reload()}
function celebrate(title,text,icon="🎉"){const box=document.querySelector("#celebration");document.querySelector("#celebrationTitle").textContent=title;document.querySelector("#celebrationText").textContent=text;document.querySelector("#celebrationIcon").textContent=icon;box.classList.add("show");if(navigator.vibrate)navigator.vibrate([120,70,160]);clearTimeout(celebrate.timer);celebrate.timer=setTimeout(()=>box.classList.remove("show"),2200)}
async function changeOwnPassword(){const password=document.querySelector("#ownNewPassword").value,confirmation=document.querySelector("#ownConfirmPassword").value,button=document.querySelector("#changeOwnPassword");if(password.length<6)return toast("A senha precisa ter pelo menos 6 caracteres",true);if(password!==confirmation)return toast("As duas senhas precisam ser iguais",true);button.disabled=true;button.textContent="Alterando...";const {error}=await supabaseClient.auth.updateUser({password});button.disabled=false;button.textContent="Alterar minha senha";if(error)return toast("Não foi possível alterar a senha",true);document.querySelector("#ownNewPassword").value="";document.querySelector("#ownConfirmPassword").value="";toast("Senha alterada com sucesso")}
async function changeOwnName(){const oldName=currentProfile?.full_name||"",name=prompt("Digite o nome que deve aparecer no BarberXP:",oldName);if(name===null)return;const clean=name.trim();if(clean.length<2)return toast("Digite um nome válido",true);const {error}=await supabaseClient.from("profiles").update({full_name:clean,updated_at:new Date().toISOString()}).eq("id",currentUser.id);if(error)return toast("Não foi possível alterar o nome",true);currentProfile.full_name=clean;const initials=clean.split(" ").map(part=>part[0]).slice(0,2).join("").toUpperCase();document.querySelector("#profileName").textContent=clean;document.querySelector("#profileAvatar").textContent=initials;document.querySelector("#dropdownName").textContent=clean;document.querySelector("#greeting").textContent="Olá, "+clean.split(" ")[0]+" 👊";document.querySelector("#userDropdown").classList.add("hidden");document.querySelector("#profileMenuButton").classList.remove("open");render();toast("Nome atualizado no seu perfil")}
async function createMember(){if(currentProfile?.role!=="leader")return;const name=document.querySelector("#newMemberName").value.trim(),email=document.querySelector("#newMemberEmail").value.trim().toLowerCase(),password=document.querySelector("#newMemberPassword").value,status=document.querySelector("#memberStatus"),button=document.querySelector("#prepareMember");if(!name)return toast("Informe o nome do barbeiro",true);if(!email||!email.includes("@"))return toast("Informe um e-mail válido",true);if(password.length<6)return toast("A senha precisa ter pelo menos 6 caracteres",true);button.disabled=true;button.textContent="Criando acesso...";status.textContent="";const secondary=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false}});const {error}=await secondary.auth.signUp({email,password,options:{data:{full_name:name}}});button.disabled=false;button.textContent="＋ Criar acesso de barbeiro";if(error){status.style.color="#fca5a5";status.textContent=error.message.includes("already")?"Este e-mail já está cadastrado.":"Não foi possível criar o acesso agora.";return}status.style.color="#4ade80";status.textContent="Acesso criado. O barbeiro deve confirmar o e-mail antes do primeiro login.";document.querySelector("#newMemberName").value="";document.querySelector("#newMemberEmail").value="";document.querySelector("#newMemberPassword").value="";toast("Acesso de "+name+" criado com sucesso")}
async function saveMember(id){const input=document.querySelector('[data-member-name="'+id+'"]'),name=input?.value.trim();if(!name)return toast("Informe o nome do barbeiro",true);const {error}=await supabaseClient.from("profiles").update({full_name:name,updated_at:new Date().toISOString()}).eq("id",id);if(error)return toast("Não foi possível salvar o nome",true);const member=teamMembers.find(item=>item.id===id);if(member)member.full_name=name;render();toast("Nome atualizado com sucesso")}
async function toggleMember(id,isActive){const next=!isActive,member=teamMembers.find(item=>item.id===id);if(!member)return;if(isActive&&!confirm("Desativar o acesso de "+member.full_name+"?"))return;const {error}=await supabaseClient.from("profiles").update({active:next,updated_at:new Date().toISOString()}).eq("id",id);if(error)return toast("Não foi possível alterar o acesso",true);member.active=next;render();toast(next?"Acesso reativado":"Acesso desativado",!next)}
async function resetMemberPassword(email){if(!confirm("Enviar redefinição de senha para "+email+"?"))return;const {error}=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo:"https://barberxp.pages.dev"});if(error)return toast("Não foi possível enviar o e-mail",true);toast("E-mail de redefinição enviado")}
function saveRules(){document.querySelectorAll(".rule-label").forEach(i=>actions[Number(i.dataset.index)].label=i.value.trim()||"Serviço");document.querySelectorAll(".rule-xp").forEach(i=>actions[Number(i.dataset.index)].xp=Math.max(0,Number(i.value)||0));document.querySelectorAll(".rule-points").forEach(i=>actions[Number(i.dataset.index)].points=Math.max(0,Number(i.value)||0));state.actionRules=actions;render();toast("Serviços e pontuação atualizados")}
async function saveRewardSettings(){document.querySelectorAll(".reward-name").forEach(i=>rewards[Number(i.dataset.index)].name=i.value.trim()||"Prêmio");document.querySelectorAll(".reward-desc").forEach(i=>rewards[Number(i.dataset.index)].desc=i.value.trim()||"Recompensa da temporada");document.querySelectorAll(".reward-price").forEach(i=>rewards[Number(i.dataset.index)].price=Math.max(1,Number(i.value)||1));const {error}=await supabaseClient.from("app_configs").upsert({config_key:"rewards",config_value:rewards,updated_by:currentUser.id,updated_at:new Date().toISOString()});if(error)return toast("Não foi possível salvar os prêmios",true);render();toast("Prêmios mensais atualizados para toda a equipe")}
async function saveMissionSettings(){document.querySelectorAll(".mission-name").forEach(i=>missionRules[Number(i.dataset.index)].name=i.value.trim()||"Missão diária");document.querySelectorAll(".mission-desc").forEach(i=>missionRules[Number(i.dataset.index)].desc=i.value.trim()||"Complete a meta do dia");document.querySelectorAll(".mission-goal").forEach(i=>missionRules[Number(i.dataset.index)].goal=Math.max(1,Number(i.value)||1));document.querySelectorAll(".mission-bonus-points").forEach(i=>missionRules[Number(i.dataset.index)].bonusPoints=Math.max(0,Number(i.value)||0));document.querySelectorAll(".mission-bonus-xp").forEach(i=>missionRules[Number(i.dataset.index)].bonusXp=Math.max(0,Number(i.value)||0));document.querySelectorAll(".mission-key").forEach(i=>{const mission=missionRules[Number(i.dataset.index)];mission.key=i.value;mission.icon=actionIcons[i.value]||"◆"});const {error}=await supabaseClient.from("app_configs").upsert({config_key:"missions",config_value:missionRules,updated_by:currentUser.id,updated_at:new Date().toISOString()});if(error)return toast("Não foi possível salvar as missões",true);render();toast("Missões e bônus atualizados para toda a equipe")}
function saveSeasonSettings(){const name=document.querySelector("#seasonName").value.trim()||"Temporada mensal",start=document.querySelector("#seasonStart").value.trim(),end=document.querySelector("#seasonEnd").value.trim(),startDate=parseBrazilDate(start),endDate=parseBrazilDate(end);if(!startDate||!endDate||endDate<startDate)return toast("Confira as datas da temporada",true);state.season={...(state.season||{}),name,start,end,prize:document.querySelector("#seasonPrize").value.trim()||initial.season.prize,active:true};render();scheduleSave();toast("Temporada atualizada com sucesso")}
function saveCampaignDraft(){const current=campaignDraft(),name=document.querySelector("#campaignName").value.trim()||"Gincana de vendas",start=document.querySelector("#campaignStart").value.trim(),end=document.querySelector("#campaignEnd").value.trim(),startDate=parseBrazilDate(start),endDate=parseBrazilDate(end);if(!startDate||!endDate||endDate<startDate)return toast("Confira as datas da próxima campanha",true);const rules=current.rules.map((rule,i)=>({...rule,points:Math.max(0,Number(document.querySelector('[data-campaign-rule="'+i+'"]')?.value)||0)}));state.nextCampaign={...current,name,start,end,prize:document.querySelector("#campaignPrize").value.trim()||"Prêmio especial da campanha",minimumPoints:Math.max(0,Number(document.querySelector("#campaignMinimum").value)||0),bonusGoal:Math.max(0,Number(document.querySelector("#campaignBonusGoal").value)||0),bonusValue:Math.max(0,Number(document.querySelector("#campaignBonusValue").value)||0),status:"draft",rules};scheduleSave();render();toast("Rascunho da próxima campanha salvo")}
async function register(key){const t=actions.find(x=>x.key===key);const {error}=await supabaseClient.from("barber_actions").insert({user_id:currentUser.id,action_key:t.key,action_label:t.label,xp:t.xp,points:t.points,status:"pending"});if(error)return toast("Não foi possível enviar o registro",true);celebrate("Registro enviado!",t.label+" foi enviado para aprovação do líder.",t.icon||"✂️")}
async function reviewAction(id,status){const action=pendingActions.find(item=>item.id===id);if(!action)return;if(status==="approved"){const result=await supabaseClient.from("barber_states").select("state").eq("user_id",action.user_id).single();if(result.error)return toast("Não foi possível carregar os pontos do barbeiro",true);const target=result.data.state||JSON.parse(JSON.stringify(initial)),key=action.action_key,actionDay=dateKeySP(action.created_at);target.xp=(Number(target.xp)||0)+(Number(action.xp)||0);target.points=(Number(target.points)||0)+(Number(action.points)||0);target.counts=target.counts||{};target.dailyBreakdown=target.dailyBreakdown||{};target.dailyStats=target.dailyStats||{};target.history=target.history||[];const dayCounts={...emptyDaily(),...(target.dailyBreakdown[actionDay]||{})},beforeCount=Number(dayCounts[key])||0;let bonusXp=0,bonusPoints=0;target.counts[key]=(target.counts[key]||0)+1;dayCounts[key]=beforeCount+1;target.dailyBreakdown[actionDay]=dayCounts;target.dailyStats[actionDay]=Object.values(dayCounts).reduce((sum,value)=>sum+(Number(value)||0),0);target.dayKey=todayKey;target.dailyCounts={...emptyDaily(),...(target.dailyBreakdown[todayKey]||{})};target.history.unshift([key,action.action_label,Number(action.xp)||0,"Aprovado pelo líder • "+new Date(action.created_at).toLocaleString("pt-BR",{timeZone:"America/Sao_Paulo"}),"plus",Number(action.points)||0,"action:"+id]);for(const mission of missionRules.filter(item=>item.key===key&&beforeCount<item.goal&&dayCounts[key]>=item.goal)){bonusXp+=Number(mission.bonusXp)||0;bonusPoints+=Number(mission.bonusPoints)||0;target.xp+=Number(mission.bonusXp)||0;target.points+=Number(mission.bonusPoints)||0;target.history.unshift(["mission","Missão concluída: "+mission.name,Number(mission.bonusXp)||0,"Bônus do dia "+actionDay.split("-").reverse().join("/"),"plus",Number(mission.bonusPoints)||0,"bonus:"+id])}target.approvalBonuses=target.approvalBonuses||{};target.approvalBonuses[id]={xp:bonusXp,points:bonusPoints,dayKey:actionDay};const saved=await supabaseClient.from("barber_states").update({state:target,updated_at:new Date().toISOString()}).eq("user_id",action.user_id);if(saved.error)return toast("Não foi possível liberar os pontos",true)}const reviewed=await supabaseClient.from("barber_actions").update({status,reviewed_by:currentUser.id,reviewed_at:new Date().toISOString()}).eq("id",id);if(reviewed.error)return toast("Não foi possível concluir a aprovação",true);pendingActions=pendingActions.filter(item=>item.id!==id);if(status==="approved")recentApprovedActions.unshift({...action,status:"approved",reviewed_at:new Date().toISOString()});render();if(status==="approved")celebrate("Serviço aprovado!","XP e pontos liberados para "+action.full_name+".","✅");else toast("Registro recusado",true)}
async function undoApprovedAction(id){const action=recentApprovedActions.find(item=>String(item.id)===String(id));if(!action)return toast("Serviço aprovado não encontrado",true);if(!confirm("Desfazer este serviço aprovado? O XP, os pontos e a contagem serão retirados do barbeiro."))return;const result=await supabaseClient.from("barber_states").select("state").eq("user_id",action.user_id).single();if(result.error)return toast("Não foi possível carregar os dados do barbeiro",true);const target=result.data.state||{},key=action.action_key,bonus=target.approvalBonuses?.[id]||{xp:0,points:0},actionDay=bonus.dayKey||dateKeySP(action.created_at);target.xp=Math.max(0,(Number(target.xp)||0)-(Number(action.xp)||0)-(Number(bonus.xp)||0));target.points=Math.max(0,(Number(target.points)||0)-(Number(action.points)||0)-(Number(bonus.points)||0));target.counts=target.counts||{};target.dailyBreakdown=target.dailyBreakdown||{};target.dailyStats=target.dailyStats||{};target.counts[key]=Math.max(0,(Number(target.counts[key])||0)-1);const dayCounts={...emptyDaily(),...(target.dailyBreakdown[actionDay]||{})};dayCounts[key]=Math.max(0,(Number(dayCounts[key])||0)-1);target.dailyBreakdown[actionDay]=dayCounts;target.dailyStats[actionDay]=Object.values(dayCounts).reduce((sum,value)=>sum+(Number(value)||0),0);target.dayKey=todayKey;target.dailyCounts={...emptyDaily(),...(target.dailyBreakdown[todayKey]||{})};target.history=(target.history||[]).filter(item=>item[6]!=="action:"+id&&item[6]!=="bonus:"+id);target.history.unshift(["undo","Serviço desfeito: "+action.action_label,Number(action.xp)||0,"Correção realizada pelo líder","minus",-(Number(action.points)||0)]);if(target.approvalBonuses)delete target.approvalBonuses[id];const saved=await supabaseClient.from("barber_states").update({state:target,updated_at:new Date().toISOString()}).eq("user_id",action.user_id);if(saved.error)return toast("Não foi possível desfazer o serviço",true);const changed=await supabaseClient.from("barber_actions").update({status:"rejected",reviewed_by:currentUser.id,reviewed_at:new Date().toISOString()}).eq("id",id).eq("status","approved");if(changed.error)return toast("Os pontos foram corrigidos, mas o registro não foi atualizado",true);recentApprovedActions=recentApprovedActions.filter(item=>String(item.id)!==String(id));render();toast("Serviço desfeito e pontuação corrigida")}
function redeem(i){const r=rewards[i];if(state.points<r.price)return;state.points-=r.price;state.rewards.push(r.name);render();scheduleSave();toast(r.name+" resgatado com sucesso!")}
async function applyIncident(){const btn=document.querySelector(".incident.active"),userId=document.querySelector("#incidentPerson").value,member=teamMembers.find(item=>item.id===userId);if(!btn||!member)return toast("Selecione um barbeiro",true);const loss=Number(btn.dataset.loss),pointLoss=Number(btn.dataset.pointLoss),note=document.querySelector("#incidentNote").value.trim(),result=await supabaseClient.from("barber_states").select("state").eq("user_id",userId).single();if(result.error)return toast("Não foi possível carregar o barbeiro",true);const target=result.data.state||JSON.parse(JSON.stringify(initial)),id=crypto.randomUUID?crypto.randomUUID():Date.now().toString(36),createdAt=new Date().toISOString(),dateTime=formatDateTimeSP(createdAt),incident={id,type:selectedIncident,person:member.full_name,loss,pointLoss,date:dateTime,note,createdAt};target.incidents=target.incidents||[];target.history=target.history||[];target.incidents.unshift(incident);target.xp=Math.max(0,(Number(target.xp)||0)+loss);target.points=Math.max(0,(Number(target.points)||0)+pointLoss);target.history.unshift(["incident",selectedIncident,Math.abs(loss),dateTime+" • "+pointLoss+" pontos • Motivo: "+(note||"Sem observação"),"minus",pointLoss,id]);const saved=await supabaseClient.from("barber_states").update({state:target,updated_at:new Date().toISOString()}).eq("user_id",userId);if(saved.error)return toast("Não foi possível registrar a ocorrência",true);teamIncidents.unshift({...incident,userId});render();toast(selectedIncident+" para "+member.full_name+": "+loss+" XP e "+pointLoss+" pontos",true)}
async function undoIncident(id,userId){if(!confirm("Desfazer esta ocorrência e devolver o XP e os pontos ao barbeiro?"))return;const result=await supabaseClient.from("barber_states").select("state").eq("user_id",userId).single();if(result.error)return toast("Não foi possível carregar a ocorrência",true);const target=result.data.state||{},incident=(target.incidents||[]).find(item=>item.id===id||item.createdAt===id);if(!incident)return toast("Essa ocorrência não foi encontrada",true);target.xp=(Number(target.xp)||0)+Math.abs(Number(incident.loss)||0);target.points=(Number(target.points)||0)+Math.abs(Number(incident.pointLoss)||0);target.incidents=(target.incidents||[]).filter(item=>item!==incident);target.history=(target.history||[]).filter(item=>item[6]!==id);target.history.unshift(["undo","Ocorrência desfeita",Math.abs(Number(incident.loss)||0),formatDateTimeSP(new Date())+" • XP e "+Math.abs(Number(incident.pointLoss)||0)+" pontos devolvidos pelo líder • Motivo original: "+(incident.note||"Sem observação"),"plus",Math.abs(Number(incident.pointLoss)||0)]);const saved=await supabaseClient.from("barber_states").update({state:target,updated_at:new Date().toISOString()}).eq("user_id",userId);if(saved.error)return toast("Não foi possível desfazer a ocorrência",true);teamIncidents=teamIncidents.filter(item=>(item.id||item.createdAt)!==id);render();toast("Ocorrência desfeita: XP e pontos devolvidos")}
