function showApp(){const name=currentProfile.full_name||currentUser.email.split("@")[0],initials=name.split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase();document.querySelector("#accountEmail").textContent=currentUser.email;document.querySelector("#profileName").textContent=name;document.querySelector("#profileAvatar").textContent=initials;document.querySelector("#dropdownName").textContent=name;document.querySelector("#dropdownEmail").textContent=currentUser.email;document.querySelector("#greeting").textContent="Olá, "+name.split(" ")[0]+" 👊";document.querySelector("#authGate").classList.add("hidden");document.querySelector("#appShell").classList.remove("hidden");role=currentProfile.role==="leader"?"leader":currentProfile.role==="manager"?"manager":"barber";view=role==="leader"?"leader":role==="manager"?"manager":"dashboard";loadRemote().then(()=>{loadApprovedActions();loadSeasonLeaderboard();if(canManageOperation()){loadManagerData().then(pruneManagerPeople);clearInterval(operationPoll);operationPoll=setInterval(()=>loadManagerData().then(pruneManagerPeople),15000)}})}
async function bootstrapAuth(){const {data}=await supabaseClient.auth.getSession();if(!data.session)return;currentUser=data.session.user;const profileResult=await supabaseClient.from("profiles").select("*").eq("id",currentUser.id).single();if(profileResult.error){document.querySelector("#loginError").textContent="Perfil não encontrado. Fale com o líder.";return}currentProfile=profileResult.data;if(!currentProfile.active){await supabaseClient.auth.signOut();document.querySelector("#loginError").textContent="Seu acesso está desativado. Fale com o líder.";return}showApp()}
