const DEFAULT_MISSION_RULES = [
  { key: "cortes", name: "Produção afiada", goal: 8, bonusXp: 25, bonusPoints: 5 },
  { key: "barbas", name: "Barba em dia", goal: 4, bonusXp: 25, bonusPoints: 5 },
  { key: "extras", name: "Experiência completa", goal: 2, bonusXp: 25, bonusPoints: 5 },
  { key: "produtos", name: "Venda com propósito", goal: 2, bonusXp: 25, bonusPoints: 5 },
  { key: "assinaturas", name: "Clube crescendo", goal: 1, bonusXp: 25, bonusPoints: 5 },
];

export default {
  async fetch(request, env) {
    const email = request.headers.get("oai-authenticated-user-email") || "acesso@edershow.com.br";
    const isLeader = email.toLowerCase() === "edershow08@gmail.com";
    const url = new URL(request.url);
    if (url.pathname.startsWith("/api/")) {
      if (!env?.DB) return Response.json({ error: "Banco de dados indisponível" }, { status: 503 });
      await ensureDatabase(env.DB);
      if (url.pathname === "/api/state" && request.method === "GET") {
        const row = await env.DB.prepare("SELECT state_json, full_name, role, updated_at FROM barberxp_state WHERE email = ?")
          .bind(email.toLowerCase()).first();
        const savedState = row ? normalizeServerState(JSON.parse(row.state_json)) : null;
        if (row && savedState.changed) {
          await env.DB.prepare("UPDATE barberxp_state SET state_json = ?, updated_at = CURRENT_TIMESTAMP WHERE email = ?")
            .bind(JSON.stringify(savedState.state), email.toLowerCase()).run();
        }
        return Response.json({
          state: savedState ? savedState.state : null,
          profile: row ? { name: row.full_name, role: row.role, updatedAt: row.updated_at } : null,
        });
      }
      if (url.pathname === "/api/state" && request.method === "PUT") {
        const state = await request.json();
        if (!state || typeof state !== "object" || typeof state.xp !== "number" || !state.counts) {
          return Response.json({ error: "Dados inválidos" }, { status: 400 });
        }
        const normalized = normalizeServerState(state).state;
        const fullName = authenticatedName(request) || (isLeader ? "Éder Henrique" : email.split("@")[0]);
        const role = isLeader ? "leader" : "barber";
        await env.DB.prepare(`
          INSERT INTO barberxp_state (email, full_name, role, state_json, updated_at)
          VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)
          ON CONFLICT(email) DO UPDATE SET
            full_name = excluded.full_name,
            role = excluded.role,
            state_json = excluded.state_json,
            updated_at = CURRENT_TIMESTAMP
        `).bind(email.toLowerCase(), fullName, role, JSON.stringify(normalized)).run();
        return Response.json({ ok: true });
      }
      if (url.pathname === "/api/config" && request.method === "GET") {
        const result = await env.DB.prepare("SELECT config_key, config_json FROM barberxp_config WHERE config_key IN ('rewards', 'missions')").all();
        const config = { rewards: null, missions: null };
        for (const row of result.results || []) Object.assign(config, JSON.parse(row.config_json));
        return Response.json(config);
      }
      if (url.pathname === "/api/config" && request.method === "PUT") {
        if (!isLeader) return Response.json({ error: "Acesso restrito ao líder" }, { status: 403 });
        const config = await request.json();
        if (Array.isArray(config.rewards)) {
          if (!config.rewards.length || config.rewards.some(item => !item.name || !Number.isFinite(Number(item.price)))) {
            return Response.json({ error: "Prêmios inválidos" }, { status: 400 });
          }
          const clean = {
            rewards: config.rewards.slice(0, 20).map(item => ({
              icon: String(item.icon || "◆").slice(0, 4),
              name: String(item.name).slice(0, 80),
              desc: String(item.desc || "").slice(0, 180),
              price: Math.max(1, Math.round(Number(item.price))),
            })),
          };
          await saveConfig(env.DB, "rewards", clean);
          return Response.json({ ok: true });
        }
        if (Array.isArray(config.missions)) {
          const allowed = new Set(["cortes", "barbas", "extras", "produtos", "assinaturas"]);
          if (config.missions.length !== 5 || config.missions.some(item => !allowed.has(item.key) || !item.name || !Number.isFinite(Number(item.goal)))) {
            return Response.json({ error: "Missões inválidas" }, { status: 400 });
          }
          const clean = {
            missions: config.missions.map(item => ({
              key: item.key,
              icon: String(item.icon || "◆").slice(0, 4),
              name: String(item.name).slice(0, 80),
              desc: String(item.desc || "").slice(0, 180),
              goal: Math.max(1, Math.round(Number(item.goal))),
              bonusXp: Math.max(0, Math.min(1000, Math.round(Number(item.bonusXp || 0)))),
              bonusPoints: Math.max(0, Math.min(500, Math.round(Number(item.bonusPoints || 0)))),
            })),
          };
          await saveConfig(env.DB, "missions", clean);
          return Response.json({ ok: true });
        }
        return Response.json({ error: "Configuração inválida" }, { status: 400 });
      }
      if (url.pathname === "/api/actions" && request.method === "POST") {
        const action = await request.json();
        const allowed = new Set(["cortes", "barbas", "extras", "produtos", "assinaturas"]);
        if (!allowed.has(action.key) || !action.label || !Number.isFinite(Number(action.xp)) || !Number.isFinite(Number(action.points))) {
          return Response.json({ error: "Registro inválido" }, { status: 400 });
        }
        const fullName = authenticatedName(request) || (isLeader ? "Éder Henrique" : email.split("@")[0]);
        const result = await env.DB.prepare(`
          INSERT INTO barberxp_actions (email, full_name, action_key, action_label, xp, points, status)
          VALUES (?, ?, ?, ?, ?, ?, 'pending')
        `).bind(email.toLowerCase(), fullName, action.key, String(action.label).slice(0, 80), Math.max(0, Math.min(500, Math.round(Number(action.xp)))), Math.max(0, Math.min(100, Math.round(Number(action.points))))).run();
        return Response.json({ ok: true, id: result.meta?.last_row_id }, { status: 201 });
      }
      if (url.pathname === "/api/actions" && request.method === "GET") {
        if (!isLeader) return Response.json({ error: "Acesso restrito ao líder" }, { status: 403 });
        const result = await env.DB.prepare("SELECT id, email, full_name, action_key, action_label, xp, points, status, created_at FROM barberxp_actions WHERE status = 'pending' ORDER BY created_at ASC").all();
        return Response.json({ actions: result.results || [] });
      }
      const reviewMatch = url.pathname.match(/^\/api\/actions\/(\d+)$/);
      if (reviewMatch && request.method === "PATCH") {
        if (!isLeader) return Response.json({ error: "Acesso restrito ao líder" }, { status: 403 });
        const review = await request.json();
        if (!["approved", "rejected"].includes(review.status)) return Response.json({ error: "Decisão inválida" }, { status: 400 });
        const action = await env.DB.prepare("SELECT * FROM barberxp_actions WHERE id = ? AND status = 'pending'").bind(Number(reviewMatch[1])).first();
        if (!action) return Response.json({ error: "Registro já analisado ou inexistente" }, { status: 404 });
        if (review.status === "rejected") {
          await env.DB.prepare("UPDATE barberxp_actions SET status = 'rejected', reviewed_at = CURRENT_TIMESTAMP, reviewed_by = ? WHERE id = ? AND status = 'pending'")
            .bind(email.toLowerCase(), action.id).run();
          return Response.json({ ok: true, status: "rejected" });
        }
        const profile = await env.DB.prepare("SELECT state_json FROM barberxp_state WHERE email = ?").bind(action.email).first();
        if (!profile) return Response.json({ error: "O perfil do barbeiro ainda não foi sincronizado" }, { status: 409 });
        const normalized = normalizeServerState(JSON.parse(profile.state_json)).state;
        const dateKey = dateKeyInSaoPaulo(new Date());
        normalized.counts ||= {};
        normalized.dailyCounts ||= {};
        normalized.dailyStats ||= {};
        normalized.history ||= [];
        normalized.missionBonuses ||= {};
        normalized.xp = Number(normalized.xp || 0) + Number(action.xp);
        normalized.points = Number(normalized.points || 0) + Number(action.points);
        normalized.counts[action.action_key] = Number(normalized.counts[action.action_key] || 0) + 1;
        normalized.dailyCounts[action.action_key] = Number(normalized.dailyCounts[action.action_key] || 0) + 1;
        normalized.dailyStats[dateKey] = Number(normalized.dailyStats[dateKey] || 0) + 1;
        normalized.history.unshift([action.action_key, action.action_label, Number(action.xp), "Aprovado pelo líder", "plus"]);
        normalized.history = normalized.history.slice(0, 20);
        const missionsRow = await env.DB.prepare("SELECT config_json FROM barberxp_config WHERE config_key = 'missions'").first();
        const missions = missionsRow ? JSON.parse(missionsRow.config_json).missions : DEFAULT_MISSION_RULES;
        const mission = missions.find(item => item.key === action.action_key);
        const bonusKey = dateKey + ":" + action.action_key;
        let bonus = null;
        if (mission && normalized.dailyCounts[action.action_key] >= mission.goal && !normalized.missionBonuses[bonusKey]) {
          normalized.missionBonuses[bonusKey] = true;
          normalized.xp += Number(mission.bonusXp || 0);
          normalized.points += Number(mission.bonusPoints || 0);
          normalized.history.unshift(["mission", "Missão concluída: "+mission.name, Number(mission.bonusXp || 0), "Bônus diário aprovado", "plus"]);
          bonus = { xp: Number(mission.bonusXp || 0), points: Number(mission.bonusPoints || 0), mission: mission.name };
        }
        await env.DB.batch([
          env.DB.prepare("UPDATE barberxp_state SET state_json = ?, updated_at = CURRENT_TIMESTAMP WHERE email = ?").bind(JSON.stringify(normalized), action.email),
          env.DB.prepare("UPDATE barberxp_actions SET status = 'approved', reviewed_at = CURRENT_TIMESTAMP, reviewed_by = ? WHERE id = ? AND status = 'pending'").bind(email.toLowerCase(), action.id),
        ]);
        return Response.json({ ok: true, status: "approved", bonus });
      }
      if (url.pathname === "/api/ranking" && request.method === "GET") {
        const result = await env.DB.prepare("SELECT email, full_name, state_json FROM barberxp_state ORDER BY updated_at DESC").all();
        const ranking = (result.results || []).map(row => {
          const saved = normalizeServerState(JSON.parse(row.state_json)).state;
          const words = row.full_name.trim().split(/\s+/);
          return {
            name: row.full_name,
            initials: (words[0]?.[0] || "") + (words[1]?.[0] || words[0]?.[1] || ""),
            xp: Number(saved.xp || 0),
            points: Number(saved.points || 0),
            stats: saved.counts || {},
            me: row.email === email.toLowerCase(),
          };
        }).sort((a, b) => b.points - a.points);
        return Response.json({ ranking });
      }
      if (url.pathname === "/api/team" && request.method === "GET") {
        if (!isLeader) return Response.json({ error: "Acesso restrito ao líder" }, { status: 403 });
        const result = await env.DB.prepare("SELECT email, full_name, role, state_json, updated_at FROM barberxp_state ORDER BY updated_at DESC").all();
        return Response.json({
          team: (result.results || []).map(row => ({
            email: row.email,
            name: row.full_name,
            role: row.role,
            state: JSON.parse(row.state_json),
            updatedAt: row.updated_at,
          })),
        });
      }
      return Response.json({ error: "Rota não encontrada" }, { status: 404 });
    }
    const page = html.replaceAll("__USER_EMAIL__", email.replace(/[<>&"']/g, "")).replaceAll("__IS_LEADER__", isLeader ? "true" : "false");
    return new Response(page, {
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store",
      },
    });
  },
};

async function ensureDatabase(db) {
  await db.batch([
    db.prepare(`
      CREATE TABLE IF NOT EXISTS barberxp_state (
        email TEXT PRIMARY KEY,
        full_name TEXT NOT NULL,
        role TEXT NOT NULL CHECK (role IN ('leader', 'barber')),
        state_json TEXT NOT NULL,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
      )
    `),
    db.prepare("CREATE INDEX IF NOT EXISTS barberxp_state_role_idx ON barberxp_state (role, updated_at)"),
    db.prepare(`
      CREATE TABLE IF NOT EXISTS barberxp_config (
        config_key TEXT PRIMARY KEY,
        config_json TEXT NOT NULL,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
      )
    `),
    db.prepare(`
      CREATE TABLE IF NOT EXISTS barberxp_actions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        email TEXT NOT NULL,
        full_name TEXT NOT NULL,
        action_key TEXT NOT NULL,
        action_label TEXT NOT NULL,
        xp INTEGER NOT NULL,
        points INTEGER NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending'
          CHECK (status IN ('pending', 'approved', 'rejected')),
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        reviewed_at TEXT,
        reviewed_by TEXT
      )
    `),
    db.prepare("CREATE INDEX IF NOT EXISTS barberxp_actions_status_idx ON barberxp_actions (status, created_at)"),
  ]);
}

function normalizeServerState(state) {
  const month = currentMonthInSaoPaulo();
  if (!state.pointsMonth) {
    state.pointsMonth = month;
    return { state, changed: true };
  }
  if (state.pointsMonth !== month) {
    state.points = 0;
    state.pointsMonth = month;
    state.rewards = [];
    return { state, changed: true };
  }
  return { state, changed: false };
}

async function saveConfig(db, key, value) {
  await db.prepare(`
    INSERT INTO barberxp_config (config_key, config_json, updated_at)
    VALUES (?, ?, CURRENT_TIMESTAMP)
    ON CONFLICT(config_key) DO UPDATE SET
      config_json = excluded.config_json,
      updated_at = CURRENT_TIMESTAMP
  `).bind(key, JSON.stringify(value)).run();
}

function currentMonthInSaoPaulo() {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/Sao_Paulo",
    year: "numeric",
    month: "2-digit",
  }).formatToParts(new Date());
  const year = parts.find(part => part.type === "year")?.value;
  const month = parts.find(part => part.type === "month")?.value;
  return `${year}-${month}`;
}

function dateKeyInSaoPaulo(date) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/Sao_Paulo",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(date);
  const value = type => parts.find(part => part.type === type)?.value;
  return `${value("year")}-${value("month")}-${value("day")}`;
}

function authenticatedName(request) {
  const encoding = request.headers.get("oai-authenticated-user-full-name-encoding");
  const encoded = request.headers.get("oai-authenticated-user-full-name");
  if (!encoded || encoding !== "percent-encoded-utf-8") return "";
  try {
    return decodeURIComponent(encoded);
  } catch {
    return "";
  }
}
